// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"Como usar este guia","html":"<p>Este guia faz parte da formação da equipe para o uso da plataforma de reforço escolar da rede municipal. Ele pode ser lido de uma vez ou consultado por capítulo, quando surgir uma dúvida.</p><h3>Ao final, você será capaz de</h3><ul><li>Explicar a um colega ou a um responsável como o reforço funciona.</li><li>Entrar na plataforma e encontrar as suas turmas.</li><li>Ler o mapa da turma e identificar o que retomar em sala.</li><li>Usar as informações do reforço no planejamento da semana.</li><li>Avisar os responsáveis quando um aluno precisa de reforço.</li><li>Usar a plataforma com ética e proteger os dados dos alunos.</li></ul><h3>Como estudar</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th><th>Tempo</th></tr></thead><tbody><tr><td data-rotulo=\"Etapa\">Leitura</td><td data-rotulo=\"O que fazer\">Ler os capítulos 2 a 7 e acompanhar as figuras.</td><td data-rotulo=\"Tempo\">1 h 30</td></tr><tr><td data-rotulo=\"Etapa\">Prática</td><td data-rotulo=\"O que fazer\">Entrar na plataforma e repetir os exemplos com uma turma sua.</td><td data-rotulo=\"Tempo\">1 h 30</td></tr><tr><td data-rotulo=\"Etapa\">Ética e dados</td><td data-rotulo=\"O que fazer\">Ler os capítulos 12 e 13.</td><td data-rotulo=\"Tempo\">30 min</td></tr><tr><td data-rotulo=\"Etapa\">Verificação</td><td data-rotulo=\"O que fazer\">Responder às questões do capítulo 15.</td><td data-rotulo=\"Tempo\">30 min</td></tr></tbody></table></div><div class=\"nota\"><b>Dados dos exemplos</b><br/>Os nomes, as turmas e os números usados nos exemplos e nos gráficos deste guia são fictícios. Eles servem para mostrar como ler as telas.</div>"},{"id":"c2","titulo":"O reforço e o seu papel","html":"<p>A plataforma oferece reforço escolar individual em todos os componentes curriculares do ano do aluno, alinhado à BNCC. O reforço acontece sem depender de você: o aluno estuda no próprio ritmo, e a plataforma organiza o caminho.</p><p>O seu papel é usar o que a plataforma mostra. Você passa a saber, por aluno e por habilidade, onde a turma está bem e onde precisa de atenção.</p><div class=\"tb\"><table><thead><tr><th>Quem</th><th>O que faz no reforço</th></tr></thead><tbody><tr><td data-rotulo=\"Quem\">Aluno</td><td data-rotulo=\"O que faz no reforço\">Estuda as trilhas, no próprio ritmo, na matéria que escolher.</td></tr><tr><td data-rotulo=\"Quem\">Responsável</td><td data-rotulo=\"O que faz no reforço\">Acompanha a evolução do aluno e organiza o horário de estudo em casa.</td></tr><tr><td data-rotulo=\"Quem\">Professor</td><td data-rotulo=\"O que faz no reforço\">Acompanha as turmas, leva as informações para a aula e avisa os responsáveis.</td></tr><tr><td data-rotulo=\"Quem\">Direção</td><td data-rotulo=\"O que faz no reforço\">Organiza turmas e professores e entrega o acesso aos alunos e aos responsáveis.</td></tr><tr><td data-rotulo=\"Quem\">Coordenação pedagógica</td><td data-rotulo=\"O que faz no reforço\">Aplica diagnósticos, aprova trilhas e acompanha as habilidades prioritárias.</td></tr><tr><td data-rotulo=\"Quem\">Secretaria</td><td data-rotulo=\"O que faz no reforço\">Administra a rede e acompanha os resultados de todas as escolas.</td></tr></tbody></table></div><ul><li>Você <b>não</b> precisa lançar notas no reforço.</li><li>Você <b>não</b> precisa corrigir as atividades do reforço.</li><li>Você <b>pode</b> publicar atividades para a turma, se a escola usar esse recurso.</li></ul>"},{"id":"c3","titulo":"Como o aluno estuda","html":"<p>O reforço é individual. Cada aluno entra com o próprio acesso, escolhe a matéria que quer estudar e segue um caminho montado para ele, em casa ou na escola, no tablet, no celular ou no computador.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Entrar</b><small>acesso individual entregue pela escola</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Diagnóstico</b><small>questões curtas por habilidade</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Trilha</b><small>cinco etapas por habilidade</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Tutor</b><small>dicas e perguntas, sem dar a resposta</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Evolução</b><small>três níveis de domínio</small></div></div><figcaption>Figura. O caminho do aluno no reforço.</figcaption></figure><h3>O diagnóstico</h3><p>O diagnóstico usa poucas questões por habilidade e para assim que tem segurança sobre o que o aluno sabe. Não é prova, não gera nota e não aparece para o aluno como aprovação ou reprovação.</p><h3>A trilha em cinco etapas</h3><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Relembrar</b><small>retoma o que o aluno já viu</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Exemplo guiado</b><small>mostra a resolução passo a passo</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Praticar</b><small>questões com retorno imediato</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Aplicar</b><small>situações do dia a dia</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Explicar</b><small>o aluno explica com as próprias palavras</small></div></div><figcaption>Figura. As cinco etapas de cada trilha.</figcaption></figure><p>Cada resposta errada indica um tipo de dificuldade. A plataforma usa essa informação para escolher a dica e a próxima questão, em vez de apenas marcar certo ou errado.</p><h3>Os três níveis</h3><figure><div class=\"niveis\"><div class=\"nv\" style=\"background:#C44536\"><b>Ainda não</b><small>não mostrou domínio</small></div><div class=\"seta\">&#8250;</div><div class=\"nv\" style=\"background:#D9920B\"><b>Quase lá</b><small>acerta parte, precisa praticar</small></div><div class=\"seta\">&#8250;</div><div class=\"nv\" style=\"background:#1E8E5A\"><b>Domina</b><small>domínio consistente</small></div></div><figcaption>Figura. A evolução do aluno em cada habilidade.</figcaption></figure><h3>A volta ao que ficou para trás</h3><p>Muitas dificuldades vêm de um conteúdo de ano anterior. Quando o aluno erra, a plataforma verifica as habilidades que servem de base e leva o aluno a elas antes de seguir.</p><figure><div class=\"escada\"><div class=\"dg\" style=\"margin-left:0mm\"><span class=\"ano\">6º ano</span><span class=\"hab\">Resolver problemas com frações</span><span class=\"sit sn\">Ainda não</span></div><div class=\"dg\" style=\"margin-left:9mm\"><span class=\"ano\">5º ano</span><span class=\"hab\">Comparar e ordenar frações</span><span class=\"sit sq\">Quase lá</span></div><div class=\"dg\" style=\"margin-left:18mm\"><span class=\"ano\">4º ano</span><span class=\"hab\">Reconhecer frações unitárias</span><span class=\"sit sd\">Domina</span></div></div><figcaption>Figura. Exemplo: a dificuldade do 6º ano tem origem em uma habilidade do 5º ano. O aluno estuda primeiro a do 5º.</figcaption></figure><div class=\"nota\"><b>O reforço não depende da aula</b><br/>Ninguém da escola precisa liberar, aplicar ou corrigir nada para o reforço acontecer. A escola oferece o acesso e acompanha.</div>"},{"id":"c4","titulo":"Seu primeiro acesso","html":"<ol class=\"passos\"><li>Abra o endereço da plataforma informado pela sua escola.</li><li>Entre com o convite recebido por e-mail ou com a conta institucional, se a rede usar login único.</li><li>Se você tiver mais de um perfil, escolha o perfil de professor.</li><li>Confira se as suas turmas aparecem em <b>Minhas turmas</b>.</li></ol><figure><div class=\"tela\"><div class=\"barra\"><span></span><span></span><span></span><em>{{REDE}}</em></div><div class=\"app\"><aside><div class=\"logo\">{{REDE}}</div><div class=\"pf\">Professor(a)</div><div class=\"it at\">Minhas turmas</div><div class=\"it\">Mapa da turma</div><div class=\"it\">Trilhas</div><div class=\"it\">Atividades da turma</div><div class=\"it\">Abrir aula</div><div class=\"it\">Atividades</div><div class=\"it\">Redações</div><div class=\"it\">Retornos para revisar</div><div class=\"it\">Avisar as famílias</div><div class=\"it\">Formação</div></aside><main><div class=\"cab\"><b>Minhas Turmas</b></div><div class=\"corpo\"><div class=\"lst\"><div class=\"li\"><b>6º ano B · Matemática</b><small>28 alunos · turno da manhã</small><span class=\"bt\">Abrir</span></div><div class=\"li\"><b>7º ano A · Matemática</b><small>31 alunos · turno da manhã</small><span class=\"bt\">Abrir</span></div><div class=\"li\"><b>7º ano C · Matemática</b><small>29 alunos · turno da tarde</small><span class=\"bt\">Abrir</span></div></div></div></main></div></div><figcaption>Ilustração da tela. Minhas turmas é a porta de entrada. O menu fica à esquerda.</figcaption></figure><div class=\"nota\"><b>Nenhuma turma apareceu?</b><br/>Quem liga o professor às turmas é a direção da escola, no quadro de atribuições. Peça à direção para fazer o vínculo.</div>"},{"id":"c5","titulo":"O seu menu, tela por tela","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>No menu</th><th>Para que serve</th><th>Quando usar</th></tr></thead><tbody><tr><td data-rotulo=\"No menu\">Minhas turmas</td><td data-rotulo=\"Para que serve\">Lista das turmas atribuídas a você.</td><td data-rotulo=\"Quando usar\">Sempre que entrar.</td></tr><tr><td data-rotulo=\"No menu\">Mapa da turma</td><td data-rotulo=\"Para que serve\">Quadro de alunos por habilidade, com o nível de cada um.</td><td data-rotulo=\"Quando usar\">Toda semana, antes de planejar.</td></tr><tr><td data-rotulo=\"No menu\">Trilhas</td><td data-rotulo=\"Para que serve\">Sequências de atividades por habilidade da BNCC, com a biblioteca da rede.</td><td data-rotulo=\"Quando usar\">Ao buscar material para uma habilidade.</td></tr><tr><td data-rotulo=\"No menu\">Atividades da turma</td><td data-rotulo=\"Para que serve\">Registro de aulas e publicação de atividades.</td><td data-rotulo=\"Quando usar\">Se a escola usa atividades de turma.</td></tr><tr><td data-rotulo=\"No menu\">Abrir aula</td><td data-rotulo=\"Para que serve\">Modo sala de aula: os alunos entram pelo código no projetor.</td><td data-rotulo=\"Quando usar\">Em aulas com uso da plataforma.</td></tr><tr><td data-rotulo=\"No menu\">Atividades</td><td data-rotulo=\"Para que serve\">Atividades que você criou e as entregas dos alunos.</td><td data-rotulo=\"Quando usar\">Ao acompanhar entregas.</td></tr><tr><td data-rotulo=\"No menu\">Redações</td><td data-rotulo=\"Para que serve\">Propostas de redação com retorno por parágrafo.</td><td data-rotulo=\"Quando usar\">Em propostas de produção de texto.</td></tr><tr><td data-rotulo=\"No menu\">Retornos para revisar</td><td data-rotulo=\"Para que serve\">Retornos que aguardam a sua revisão.</td><td data-rotulo=\"Quando usar\">Toda semana.</td></tr><tr><td data-rotulo=\"No menu\">Avisar as famílias</td><td data-rotulo=\"Para que serve\">Indicação de reforço numa matéria aos responsáveis.</td><td data-rotulo=\"Quando usar\">Quando um aluno precisa de atenção.</td></tr><tr><td data-rotulo=\"No menu\">Formação</td><td data-rotulo=\"Para que serve\">Este guia e os demais materiais de treinamento.</td><td data-rotulo=\"Quando usar\">Em caso de dúvida.</td></tr></tbody></table></div>"},{"id":"c6","titulo":"Como ler o mapa da turma","html":"<p>O mapa cruza os alunos com as habilidades avaliadas. Cada célula mostra o nível do aluno naquela habilidade. Você pode filtrar por componente.</p><figure><div class=\"tela\"><div class=\"barra\"><span></span><span></span><span></span><em>{{REDE}}</em></div><div class=\"app\"><aside><div class=\"logo\">{{REDE}}</div><div class=\"pf\">Professor(a)</div><div class=\"it\">Minhas turmas</div><div class=\"it at\">Mapa da turma</div><div class=\"it\">Trilhas</div><div class=\"it\">Atividades da turma</div><div class=\"it\">Abrir aula</div><div class=\"it\">Atividades</div><div class=\"it\">Redações</div><div class=\"it\">Retornos para revisar</div><div class=\"it\">Avisar as famílias</div><div class=\"it\">Formação</div></aside><main><div class=\"cab\"><b>Mapa da Turma</b><small>Alunos × habilidades por nível de domínio</small></div><div class=\"corpo\"><figure><div class=\"tb\"><table class=\"mapa\"><thead><tr><th></th><th>Frações</th><th>Decimais</th><th>Porcent.</th><th>Equações</th><th>Áreas</th><th>Gráficos</th></tr></thead><tbody><tr><td class=\"al\">Aluno A</td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno B</td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno C</td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno D</td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td></tr><tr><td class=\"al\">Aluno E</td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td></tr></tbody></table></div><div class=\"leg\"><span><i style=\"background:#C44536\"></i>Ainda não</span><span><i style=\"background:#D9920B\"></i>Quase lá</span><span><i style=\"background:#1E8E5A\"></i>Domina</span><span><i style=\"background:#E3E7ED\"></i>Sem avaliação</span></div><figcaption></figcaption></figure></div></main></div></div><figcaption>Ilustração da tela. No mapa, cada linha é um aluno e cada coluna é uma habilidade.</figcaption></figure><h3>Três leituras do mapa</h3><figure><div class=\"tb\"><table class=\"mapa\"><thead><tr><th></th><th>Frações</th><th>Decimais</th><th>Porcent.</th><th>Equações</th><th>Áreas</th><th>Gráficos</th></tr></thead><tbody><tr><td class=\"al\">Aluno A</td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno B</td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno C</td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno D</td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td></tr><tr><td class=\"al\">Aluno E</td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno F</td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr><tr><td class=\"al\">Aluno G</td><td><span class=\"c n\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c v\"></span></td><td><span class=\"c v\"></span></td></tr><tr><td class=\"al\">Aluno H</td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c q\"></span></td><td><span class=\"c d\"></span></td><td><span class=\"c d\"></span></td></tr></tbody></table></div><div class=\"leg\"><span><i style=\"background:#C44536\"></i>Ainda não</span><span><i style=\"background:#D9920B\"></i>Quase lá</span><span><i style=\"background:#1E8E5A\"></i>Domina</span><span><i style=\"background:#E3E7ED\"></i>Sem avaliação</span></div><figcaption>Mapa de exemplo (dados fictícios) de uma turma de 6º ano em Matemática.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Leitura</th><th>O que observar no exemplo</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Leitura\">Pela coluna</td><td data-rotulo=\"O que observar no exemplo\">Em Frações, cinco dos oito alunos estão em Ainda não.</td><td data-rotulo=\"O que fazer\">Retomar frações com a turma inteira.</td></tr><tr><td data-rotulo=\"Leitura\">Pela linha</td><td data-rotulo=\"O que observar no exemplo\">O Aluno D está em Ainda não em quatro habilidades.</td><td data-rotulo=\"O que fazer\">Acompanhar de perto e avisar o responsável.</td></tr><tr><td data-rotulo=\"Leitura\">Pelas células vazias</td><td data-rotulo=\"O que observar no exemplo\">O Aluno G não foi avaliado em Áreas e Gráficos.</td><td data-rotulo=\"O que fazer\">Verificar se ele está conseguindo acessar e praticar.</td></tr></tbody></table></div><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Ainda não</span><span class=\"tr\"><span class=\"br\" style=\"width:39.285714285714285%;background:#C44536\"></span></span><span class=\"vl\">11 alunos</span></div><div class=\"ln\"><span class=\"rt\">Quase lá</span><span class=\"tr\"><span class=\"br\" style=\"width:32.142857142857146%;background:#D9920B\"></span></span><span class=\"vl\">9 alunos</span></div><div class=\"ln\"><span class=\"rt\">Domina</span><span class=\"tr\"><span class=\"br\" style=\"width:28.57142857142857%;background:#1E8E5A\"></span></span><span class=\"vl\">8 alunos</span></div></div><figcaption>Gráfico (exemplo fictício). Alunos de uma turma de 28, por nível, na habilidade de frações.</figcaption></figure>"},{"id":"c7","titulo":"Do mapa ao planejamento: exemplos de uso","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · retomada com a turma</div><p><b>Situação.</b> No mapa do 6º ano B, a habilidade de frações tem a maioria dos alunos em Ainda não.</p><p><b>O que fazer.</b></p><ol><li>Reserve parte da aula da semana para retomar frações.</li><li>Comece pelo conteúdo de base: a plataforma mostra se a dificuldade vem de um ano anterior.</li><li>Em <b>Trilhas</b>, procure na biblioteca uma trilha da habilidade e use os exemplos em sala.</li><li>Na semana seguinte, volte ao mapa e veja quem passou para Quase lá ou Domina.</li></ol><p><b>Resultado esperado.</b> A coluna da habilidade passa a ter menos alunos em Ainda não. Se não mudar, converse com a coordenação.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · grupos por nível</div><p><b>Situação.</b> Você quer fazer uma atividade em grupos sobre porcentagem e não sabe como dividir a turma.</p><p><b>O que fazer.</b></p><ol><li>Abra o mapa e olhe a coluna da habilidade.</li><li>Forme grupos que misturem alunos em Domina com alunos em Quase lá.</li><li>Reúna os alunos em Ainda não em um grupo que você acompanha mais de perto.</li></ol><p><b>Resultado esperado.</b> Os grupos ficam equilibrados, e você sabe onde concentrar a sua atenção.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · um aluno que precisa de atenção</div><p><b>Situação.</b> Um aluno aparece em Ainda não em várias habilidades e não praticou nas últimas semanas.</p><p><b>O que fazer.</b></p><ol><li>Converse com o aluno para saber se ele tem onde e quando estudar.</li><li>Em <b>Avisar as famílias</b>, indique reforço na matéria para esse aluno.</li><li>Se o problema for falta de equipamento, leve o caso à direção.</li></ol><p><b>Resultado esperado.</b> O responsável recebe o aviso no celular e pode pôr o estudo na agenda do aluno. A escola busca uma alternativa de acesso, se for preciso.</p></div><div class=\"nota alerta\"><b>O que o mapa não é</b><br/>O mapa não é boletim e não serve para dar nota. Ele mostra o momento do aluno em cada habilidade e muda conforme o aluno estuda.</div>"},{"id":"c8","titulo":"Trilhas, atividades e sala de aula","html":"<h3>Trilhas</h3><p>Em <b>Trilhas</b> você consulta a biblioteca da rede, com sequências de atividades organizadas por habilidade da BNCC. Você pode duplicar uma trilha para adaptar ou criar uma nova.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Consultar</b><small>buscar a habilidade na biblioteca</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Duplicar ou criar</b><small>adaptar à sua turma</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Enviar</b><small>a coordenação aprova, se a rede exigir</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Usar</b><small>a trilha entra na biblioteca</small></div></div><figcaption>Figura. O caminho de uma trilha criada pelo professor.</figcaption></figure><h3>Abrir aula</h3><p>No modo sala de aula, você abre uma aula e os alunos entram pelo código mostrado no projetor. É útil para usar a plataforma com a turma reunida.</p><h3>Atividades da turma</h3><p>Em <b>Atividades da turma</b> você registra aulas e publica atividades. Elas são diferentes do reforço: a atividade da turma é igual para todos, e o reforço é individual.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th></th><th>Reforço</th><th>Atividade da turma</th></tr></thead><tbody><tr><td data-rotulo=\"\">Quem define</td><td data-rotulo=\"Reforço\">A plataforma, pelo diagnóstico do aluno</td><td data-rotulo=\"Atividade da turma\">O professor</td></tr><tr><td data-rotulo=\"\">Para quem</td><td data-rotulo=\"Reforço\">Cada aluno tem o seu caminho</td><td data-rotulo=\"Atividade da turma\">A turma inteira</td></tr><tr><td data-rotulo=\"\">Depende do professor</td><td data-rotulo=\"Reforço\">Não</td><td data-rotulo=\"Atividade da turma\">Sim</td></tr></tbody></table></div>"},{"id":"c9","titulo":"Redações guiadas","html":"<p>Em <b>Redações</b> você cria uma proposta de produção de texto. O aluno escreve o texto inteiro. A plataforma dá retorno parágrafo por parágrafo, sobre coesão, argumentação e gramática, e você revisa.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Proposta</b><small>você escreve o tema e o gênero</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Texto</b><small>o aluno escreve tudo</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Retorno</b><small>por parágrafo, sem reescrever</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Revisão</b><small>você confere e complementa</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Reescrita</b><small>o aluno melhora o texto</small></div></div><figcaption>Figura. O ciclo da redação guiada.</figcaption></figure><div class=\"nota\"><b>A autoria é do aluno</b><br/>A inteligência artificial aponta o que melhorar e não reescreve o texto. A última palavra sobre o retorno é sua.</div>"},{"id":"c10","titulo":"A conversa com os responsáveis","html":"<p>Os responsáveis têm acesso próprio, entregue pela escola. Eles veem de onde o aluno partiu, onde está e o que melhorou.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Você indica</b><small>reforço numa matéria, em Avisar as famílias</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>O responsável recebe</b><small>o aviso no celular</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Agenda</b><small>o estudo entra na agenda do aluno</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>O aluno estuda</b><small>e a evolução aparece para todos</small></div></div><figcaption>Figura. Do aviso do professor ao estudo em casa.</figcaption></figure><h3>Como falar</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Em vez de</th><th>Prefira</th></tr></thead><tbody><tr><td data-rotulo=\"Em vez de\">\"Ele está fraco em Matemática.\"</td><td data-rotulo=\"Prefira\">\"Ele ainda está aprendendo frações. Com 20 minutos de reforço, três vezes por semana, costuma avançar.\"</td></tr><tr><td data-rotulo=\"Em vez de\">\"A nota dela está baixa.\"</td><td data-rotulo=\"Prefira\">\"Ela já domina decimais e está quase lá em porcentagem.\"</td></tr><tr><td data-rotulo=\"Em vez de\">\"Os pais precisam cobrar.\"</td><td data-rotulo=\"Prefira\">\"O responsável pode acompanhar pelo celular e combinar um horário de estudo.\"</td></tr></tbody></table></div><ul><li>Fale em evolução e em habilidades, não em nota.</li><li>Quem cuida do aluno pode ser mãe, pai, avó, avô, tia ou tio. Use sempre a palavra responsável.</li><li>Os responsáveis podem enviar um retorno pelo painel deles. Ele chega à coordenação.</li></ul>"},{"id":"c11","titulo":"A sua rotina semanal","html":"<figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Olhar</b><small>Abrir o mapa da turma e filtrar pelo seu componente.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Escolher</b><small>Definir a habilidade a retomar e os alunos que precisam de atenção.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Agir</b><small>Retomar em sala e avisar os responsáveis.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Conferir</b><small>Ver, na semana seguinte, o que mudou no mapa.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo semanal do professor, em cerca de 15 minutos.</figcaption></figure><ul class=\"chk\"><li><span></span>Abri o mapa da turma e filtrei pelo meu componente.</li><li><span></span>Anotei a habilidade com mais alunos em Ainda não.</li><li><span></span>Verifiquei quais alunos não praticaram.</li><li><span></span>Usei Avisar as famílias para quem precisa de reforço.</li><li><span></span>Conferi se há itens em Retornos para revisar.</li></ul>"},{"id":"c12","titulo":"Ética no uso da plataforma","html":"<p>A plataforma trata de crianças e adolescentes e usa inteligência artificial. Por isso, o uso ético faz parte do trabalho de quem tem acesso de equipe. Os princípios abaixo valem para todos os perfis.</p><div class=\"tb\"><table><thead><tr><th>Princípio</th><th>O que significa na prática</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Melhor interesse do aluno</td><td data-rotulo=\"O que significa na prática\">Toda informação é usada para ajudar o aluno a aprender. Não para punir, expor ou comparar.</td></tr><tr><td data-rotulo=\"Princípio\">Decisão humana</td><td data-rotulo=\"O que significa na prática\">A inteligência artificial apoia o estudo. As decisões pedagógicas sobre o aluno são sempre de pessoas.</td></tr><tr><td data-rotulo=\"Princípio\">Transparência</td><td data-rotulo=\"O que significa na prática\">Aluno e responsáveis sabem que a plataforma existe, para que serve e o que ela mostra.</td></tr><tr><td data-rotulo=\"Princípio\">Equidade</td><td data-rotulo=\"O que significa na prática\">Quem não tem equipamento ou internet em casa não pode ser prejudicado. A escola busca alternativas de acesso.</td></tr><tr><td data-rotulo=\"Princípio\">Sigilo</td><td data-rotulo=\"O que significa na prática\">Dados de um aluno só são vistos por quem precisa deles para o trabalho.</td></tr><tr><td data-rotulo=\"Princípio\">Honestidade dos dados</td><td data-rotulo=\"O que significa na prática\">Ninguém responde pelo aluno nem altera cadastro para melhorar indicadores.</td></tr></tbody></table></div><h3>O que fazer e o que não fazer</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Faça</th><th>Não faça</th></tr></thead><tbody><tr><td data-rotulo=\"Faça\">Usar o mapa para planejar a aula e apoiar o aluno.</td><td data-rotulo=\"Não faça\">Usar o mapa para dar nota ou classificar alunos.</td></tr><tr><td data-rotulo=\"Faça\">Conversar em particular com o aluno que precisa de atenção.</td><td data-rotulo=\"Não faça\">Expor na sala quem está em Ainda não.</td></tr><tr><td data-rotulo=\"Faça\">Incentivar o aluno a tentar e a errar.</td><td data-rotulo=\"Não faça\">Responder pelo aluno ou passar as respostas.</td></tr><tr><td data-rotulo=\"Faça\">Avisar o responsável com linguagem de apoio.</td><td data-rotulo=\"Não faça\">Usar o aviso como reclamação sobre o aluno.</td></tr><tr><td data-rotulo=\"Faça\">Levar à direção o caso de quem não tem como acessar.</td><td data-rotulo=\"Não faça\">Cobrar prática de quem não tem equipamento ou internet.</td></tr></tbody></table></div><h3>Inteligência artificial: o que ela faz e o que não faz</h3><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A inteligência artificial</th><th>Situação</th></tr></thead><tbody><tr><td data-rotulo=\"A inteligência artificial\">Orienta o raciocínio do aluno com perguntas e dicas</td><td data-rotulo=\"Situação\">Faz</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Dá retorno sobre o texto do aluno, parágrafo por parágrafo</td><td data-rotulo=\"Situação\">Faz</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Entrega a resposta pronta ou reescreve o texto do aluno</td><td data-rotulo=\"Situação\">Não faz</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Recebe o nome ou a matrícula do aluno</td><td data-rotulo=\"Situação\">Não recebe</td></tr><tr><td data-rotulo=\"A inteligência artificial\">Decide nota, aprovação ou encaminhamento do aluno</td><td data-rotulo=\"Situação\">Não decide</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Se algo parecer errado</b><br/>Uma dica inadequada, um conteúdo com erro ou um comportamento estranho da plataforma devem ser comunicados à direção ou à Secretaria. O registro ajuda a corrigir para toda a rede.</div>"},{"id":"c13","titulo":"Proteção de dados","html":"<p>A Lei Geral de Proteção de Dados (Lei nº 13.709/2018) dá proteção reforçada aos dados de crianças e adolescentes. O Município é o responsável pelos dados da rede, e cada servidor responde pelo uso que faz do seu acesso.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dado</th><th>Quem vê</th><th>Cuidado</th></tr></thead><tbody><tr><td data-rotulo=\"Dado\">Nome, turma e evolução do aluno</td><td data-rotulo=\"Quem vê\">Professores da turma, direção, coordenação e Secretaria</td><td data-rotulo=\"Cuidado\">Usar só para fins pedagógicos e de gestão.</td></tr><tr><td data-rotulo=\"Dado\">Contato dos responsáveis</td><td data-rotulo=\"Quem vê\">Direção e Secretaria</td><td data-rotulo=\"Cuidado\">Não repassar a terceiros nem usar para outros assuntos.</td></tr><tr><td data-rotulo=\"Dado\">Respostas e textos do aluno</td><td data-rotulo=\"Quem vê\">Professores da turma</td><td data-rotulo=\"Cuidado\">Não divulgar, mesmo como bom exemplo, sem autorização.</td></tr><tr><td data-rotulo=\"Dado\">Seu usuário e senha</td><td data-rotulo=\"Quem vê\">Só você</td><td data-rotulo=\"Cuidado\">Não emprestar. Sair da conta em computador compartilhado.</td></tr></tbody></table></div><ul><li>Não publique telas com nome de aluno em redes sociais ou grupos de mensagens.</li><li>Para mostrar a plataforma em reuniões abertas, use dados de exemplo ou oculte os nomes.</li><li>Os dados dos alunos não são usados para publicidade nem cedidos a terceiros.</li><li>Quando um servidor deixa a escola, a direção ou a Secretaria desativa o acesso dele.</li></ul><div class=\"nota alerta\"><b>Incidente com dados</b><br/>Acesso indevido, senha compartilhada, tela exposta ou dado enviado à pessoa errada devem ser comunicados no mesmo dia à direção, que avisa a Secretaria. A Secretaria tem um encarregado de dados para tratar o caso.</div>"},{"id":"c14","titulo":"Situações e soluções","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">O aluno esqueceu como entrar.</td><td data-rotulo=\"O que fazer\">A direção gera um novo acesso em Turmas e alunos.</td></tr><tr><td data-rotulo=\"Situação\">O responsável não consegue entrar.</td><td data-rotulo=\"O que fazer\">A direção reenvia o convite ou reimprime o kit em Acesso das famílias.</td></tr><tr><td data-rotulo=\"Situação\">O mapa está vazio.</td><td data-rotulo=\"O que fazer\">A turma ainda não fez diagnóstico no componente. Fale com a coordenação.</td></tr><tr><td data-rotulo=\"Situação\">O aluno diz que o tutor não dá a resposta.</td><td data-rotulo=\"O que fazer\">É assim que funciona. O tutor ajuda o aluno a chegar à resposta.</td></tr><tr><td data-rotulo=\"Situação\">O aluno pratica muito e não avança.</td><td data-rotulo=\"O que fazer\">Veja se a dificuldade vem de um pré-requisito e retome o conteúdo de base.</td></tr><tr><td data-rotulo=\"Situação\">Encontrei um erro em uma questão.</td><td data-rotulo=\"O que fazer\">Avise a coordenação, com a matéria, o ano e a questão.</td></tr><tr><td data-rotulo=\"Situação\">Mudei de turma ou de escola.</td><td data-rotulo=\"O que fazer\">A direção atualiza o quadro de atribuições.</td></tr></tbody></table></div>"},{"id":"c15","titulo":"Por que o reforço funciona deste jeito","html":"<p>O caminho do aluno na plataforma segue o que a pesquisa em educação mostra sobre como as pessoas aprendem. Conhecer esses princípios ajuda o professor a explicar o reforço aos alunos e às famílias e a usar as mesmas ideias na aula.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>O que significa</th><th>Como aparece no reforço</th><th>Como usar na aula</th></tr></thead><tbody><tr><td data-rotulo=\"Princípio\">Partir do que o aluno sabe</td><td data-rotulo=\"O que significa\">Ensinar acima ou abaixo do nível do aluno rende pouco.</td><td data-rotulo=\"Como aparece no reforço\">O diagnóstico localiza cada habilidade em um dos três níveis.</td><td data-rotulo=\"Como usar na aula\">Verificar o que a turma sabe antes de um conteúdo novo.</td></tr><tr><td data-rotulo=\"Princípio\">Voltar à base</td><td data-rotulo=\"O que significa\">Sem o pré-requisito, o conteúdo novo não se sustenta.</td><td data-rotulo=\"Como aparece no reforço\">A plataforma leva o aluno à habilidade anterior quando ele erra.</td><td data-rotulo=\"Como usar na aula\">Retomar a habilidade de base, mesmo que seja de outro ano.</td></tr><tr><td data-rotulo=\"Princípio\">Exemplo antes da prática</td><td data-rotulo=\"O que significa\">Ver uma resolução comentada reduz o esforço inicial.</td><td data-rotulo=\"Como aparece no reforço\">A etapa Exemplo guiado vem antes de Praticar.</td><td data-rotulo=\"Como usar na aula\">Resolver um exemplo em voz alta antes de pedir exercícios.</td></tr><tr><td data-rotulo=\"Princípio\">Prática com retorno imediato</td><td data-rotulo=\"O que significa\">Saber na hora se acertou e por que errou acelera o aprendizado.</td><td data-rotulo=\"Como aparece no reforço\">Cada questão tem retorno, e o erro indica o tipo de dificuldade.</td><td data-rotulo=\"Como usar na aula\">Corrigir na mesma aula, e não dias depois.</td></tr><tr><td data-rotulo=\"Princípio\">Aplicar em situações variadas</td><td data-rotulo=\"O que significa\">O aluno só domina quando usa o que sabe em contextos novos.</td><td data-rotulo=\"Como aparece no reforço\">A etapa Aplicar traz situações do dia a dia.</td><td data-rotulo=\"Como usar na aula\">Propor problemas ligados à vida da turma.</td></tr><tr><td data-rotulo=\"Princípio\">Explicar com as próprias palavras</td><td data-rotulo=\"O que significa\">Quem explica organiza o que sabe e percebe o que falta.</td><td data-rotulo=\"Como aparece no reforço\">A última etapa pede que o aluno explique.</td><td data-rotulo=\"Como usar na aula\">Pedir que um aluno explique ao colega.</td></tr><tr><td data-rotulo=\"Princípio\">Dica, não resposta</td><td data-rotulo=\"O que significa\">A resposta pronta resolve o exercício e não ensina.</td><td data-rotulo=\"Como aparece no reforço\">O tutor orienta com perguntas e dicas.</td><td data-rotulo=\"Como usar na aula\">Responder a uma dúvida com outra pergunta.</td></tr><tr><td data-rotulo=\"Princípio\">Ritmo próprio</td><td data-rotulo=\"O que significa\">Alunos precisam de tempos diferentes.</td><td data-rotulo=\"Como aparece no reforço\">Cada aluno avança na sua trilha.</td><td data-rotulo=\"Como usar na aula\">Planejar momentos de trabalho em níveis diferentes.</td></tr></tbody></table></div><div class=\"nota\"><b>Reforço não é repetição</b><br/>Fazer de novo, do mesmo jeito, o que o aluno não entendeu costuma não funcionar. O reforço procura a origem da dificuldade e ensina por outro caminho.</div>"},{"id":"c16","titulo":"Habilidades e progressão","html":"<p>A plataforma organiza o conteúdo por habilidades da Base Nacional Comum Curricular. Uma habilidade descreve o que o aluno deve saber fazer. Elas se encadeiam de um ano para o outro, e é esse encadeamento que permite encontrar a origem de uma dificuldade.</p><figure><div class=\"escada\"><div class=\"dg\" style=\"margin-left:0mm\"><span class=\"ano\">7º ano</span><span class=\"hab\">Resolver equações do 1º grau</span><span class=\"sit sn\">Ainda não</span></div><div class=\"dg\" style=\"margin-left:9mm\"><span class=\"ano\">6º ano</span><span class=\"hab\">Usar letras para representar valores desconhecidos</span><span class=\"sit sn\">Ainda não</span></div><div class=\"dg\" style=\"margin-left:18mm\"><span class=\"ano\">5º ano</span><span class=\"hab\">Resolver problemas com as quatro operações</span><span class=\"sit sq\">Quase lá</span></div><div class=\"dg\" style=\"margin-left:27mm\"><span class=\"ano\">4º ano</span><span class=\"hab\">Compreender a relação entre multiplicação e divisão</span><span class=\"sit sd\">Domina</span></div></div><figcaption>Figura. Exemplo em Matemática: a dificuldade com equações começa nas operações do 5º ano.</figcaption></figure><figure><div class=\"escada\"><div class=\"dg\" style=\"margin-left:0mm\"><span class=\"ano\">8º ano</span><span class=\"hab\">Analisar argumentos em textos de opinião</span><span class=\"sit sn\">Ainda não</span></div><div class=\"dg\" style=\"margin-left:9mm\"><span class=\"ano\">6º ano</span><span class=\"hab\">Distinguir fato de opinião</span><span class=\"sit sq\">Quase lá</span></div><div class=\"dg\" style=\"margin-left:18mm\"><span class=\"ano\">5º ano</span><span class=\"hab\">Inferir informações implícitas em textos</span><span class=\"sit sq\">Quase lá</span></div><div class=\"dg\" style=\"margin-left:27mm\"><span class=\"ano\">4º ano</span><span class=\"hab\">Localizar informações explícitas</span><span class=\"sit sd\">Domina</span></div></div><figcaption>Figura. Exemplo em Língua Portuguesa: argumentar depende de inferir e de distinguir fato de opinião.</figcaption></figure><h3>O que isso muda no planejamento</h3><ul><li>Um aluno do 7º ano pode precisar estudar uma habilidade do 5º. Isso não é atraso do reforço. É o caminho mais curto.</li><li>Quando muitos alunos da turma têm a mesma lacuna, vale retomá-la com todos.</li><li>A habilidade do ano continua no plano de ensino. O reforço trabalha a base em paralelo.</li><li>Ao conversar com o aluno e com a família, fale em habilidades a recuperar, e não em \"conteúdo de criança menor\".</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Nível</th><th>O que o aluno mostra</th><th>O que ele precisa</th></tr></thead><tbody><tr><td data-rotulo=\"Nível\">Ainda não</td><td data-rotulo=\"O que o aluno mostra\">Não resolve, mesmo com apoio, ou resolve por acaso.</td><td data-rotulo=\"O que ele precisa\">Voltar à base, exemplos guiados, material concreto, atendimento de perto.</td></tr><tr><td data-rotulo=\"Nível\">Quase lá</td><td data-rotulo=\"O que o aluno mostra\">Resolve com dica ou em situações conhecidas. Erra quando o contexto muda.</td><td data-rotulo=\"O que ele precisa\">Prática variada e retorno sobre os erros.</td></tr><tr><td data-rotulo=\"Nível\">Domina</td><td data-rotulo=\"O que o aluno mostra\">Resolve sozinho, em contextos diferentes, e explica.</td><td data-rotulo=\"O que ele precisa\">Aplicação, desafio e apoio a colegas.</td></tr></tbody></table></div>"},{"id":"c17","titulo":"Seis padrões do mapa da turma","html":"<p>Com o tempo, o professor passa a reconhecer padrões no mapa. Cada um pede uma ação diferente.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Padrão</th><th>O que significa</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Padrão\">Uma coluna quase toda em Ainda não</td><td data-rotulo=\"O que significa\">A turma não domina aquela habilidade.</td><td data-rotulo=\"O que fazer\">Retomar com todos antes de avançar. Verificar a habilidade de base.</td></tr><tr><td data-rotulo=\"Padrão\">Uma coluna dividida ao meio</td><td data-rotulo=\"O que significa\">Metade domina e metade não.</td><td data-rotulo=\"O que fazer\">Grupos por nível ou estações.</td></tr><tr><td data-rotulo=\"Padrão\">Uma linha quase toda em Ainda não</td><td data-rotulo=\"O que significa\">Um aluno com dificuldades em várias habilidades.</td><td data-rotulo=\"O que fazer\">Conversar com o aluno, verificar frequência e levar à coordenação.</td></tr><tr><td data-rotulo=\"Padrão\">Uma linha toda em Domina</td><td data-rotulo=\"O que significa\">Aluno pronto para ir além.</td><td data-rotulo=\"O que fazer\">Desafios, projetos e monitoria ocasional.</td></tr><tr><td data-rotulo=\"Padrão\">Células vazias em um aluno</td><td data-rotulo=\"O que significa\">Ele não fez o diagnóstico daquela habilidade.</td><td data-rotulo=\"O que fazer\">Verificar se entrou na plataforma, se tem acesso e se frequenta.</td></tr><tr><td data-rotulo=\"Padrão\">Muitas células vazias na turma</td><td data-rotulo=\"O que significa\">A turma usa pouco o reforço.</td><td data-rotulo=\"O que fazer\">Reservar horário, conferir acessos e falar com a direção.</td></tr></tbody></table></div><h3>Três perguntas para fazer ao mapa toda semana</h3><ol class=\"passos\"><li><b>Qual habilidade retomar com todos?</b> Olhe a coluna com mais Ainda não.</li><li><b>Quais dois ou três alunos precisam de mim de perto?</b> Olhe as linhas.</li><li><b>Quem não está praticando?</b> Olhe as células vazias.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Cuidado na leitura</th><th>Por quê</th></tr></thead><tbody><tr><td data-rotulo=\"Cuidado na leitura\">O mapa mostra o que o aluno fez na plataforma.</td><td data-rotulo=\"Por quê\">Ele pode saber mais do que mostrou, ou ter recebido ajuda em casa.</td></tr><tr><td data-rotulo=\"Cuidado na leitura\">Uma habilidade em Ainda não não define o aluno.</td><td data-rotulo=\"Por quê\">É uma informação sobre um conteúdo, em um momento.</td></tr><tr><td data-rotulo=\"Cuidado na leitura\">O mapa muda.</td><td data-rotulo=\"Por quê\">Consulte a versão atual antes de formar grupos.</td></tr><tr><td data-rotulo=\"Cuidado na leitura\">O mapa não substitui a sua observação.</td><td data-rotulo=\"Por quê\">Junte o que ele mostra com o que você vê nas atividades.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · o mapa da sua turma</div><div class=\"q\"><b>1.</b> Qual habilidade tem mais alunos em Ainda não?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Quais alunos têm mais células vazias? O que você sabe sobre eles?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Qual será a sua primeira ação nesta semana?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c18","titulo":"Uma aula de retomada, passo a passo","html":"<p>Depois de escolher a habilidade a retomar, a aula pode seguir a mesma lógica das cinco etapas da trilha. O roteiro abaixo cabe em uma aula de cinquenta minutos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Etapa</th><th>O que o professor faz</th><th>O que os alunos fazem</th></tr></thead><tbody><tr><td data-rotulo=\"Tempo\">5 min</td><td data-rotulo=\"Etapa\">Entrada</td><td data-rotulo=\"O que o professor faz\">Deixa no quadro uma pergunta que verifica a habilidade de base.</td><td data-rotulo=\"O que os alunos fazem\">Respondem individualmente.</td></tr><tr><td data-rotulo=\"Tempo\">8 min</td><td data-rotulo=\"Etapa\">Relembrar</td><td data-rotulo=\"O que o professor faz\">Retoma a ideia central, com material concreto ou imagem.</td><td data-rotulo=\"O que os alunos fazem\">Observam, respondem, manipulam.</td></tr><tr><td data-rotulo=\"Tempo\">7 min</td><td data-rotulo=\"Etapa\">Exemplo guiado</td><td data-rotulo=\"O que o professor faz\">Resolve um exemplo em voz alta, mostrando cada decisão.</td><td data-rotulo=\"O que os alunos fazem\">Acompanham e anotam.</td></tr><tr><td data-rotulo=\"Tempo\">15 min</td><td data-rotulo=\"Etapa\">Praticar</td><td data-rotulo=\"O que o professor faz\">Circula. Atende primeiro quem está em Ainda não.</td><td data-rotulo=\"O que os alunos fazem\">Resolvem em duplas, com conferência entre colegas.</td></tr><tr><td data-rotulo=\"Tempo\">10 min</td><td data-rotulo=\"Etapa\">Aplicar</td><td data-rotulo=\"O que o professor faz\">Propõe uma situação do cotidiano.</td><td data-rotulo=\"O que os alunos fazem\">Resolvem e comparam caminhos.</td></tr><tr><td data-rotulo=\"Tempo\">5 min</td><td data-rotulo=\"Etapa\">Explicar</td><td data-rotulo=\"O que o professor faz\">Pede que escrevam, em duas linhas, como resolveram.</td><td data-rotulo=\"O que os alunos fazem\">Escrevem e entregam.</td></tr></tbody></table></div><h3>Exemplos por componente</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Componente</th><th>Habilidade a retomar</th><th>Ideia de aula</th></tr></thead><tbody><tr><td data-rotulo=\"Componente\">Matemática</td><td data-rotulo=\"Habilidade a retomar\">Comparar frações</td><td data-rotulo=\"Ideia de aula\">Tiras de papel dobradas. Depois, problema de divisão de uma pizza entre grupos de tamanhos diferentes.</td></tr><tr><td data-rotulo=\"Componente\">Língua Portuguesa</td><td data-rotulo=\"Habilidade a retomar\">Inferir informações implícitas</td><td data-rotulo=\"Ideia de aula\">Tirinhas e manchetes: \"o que o texto não diz, mas dá a entender?\" Em duplas, justificar com trechos.</td></tr><tr><td data-rotulo=\"Componente\">Ciências</td><td data-rotulo=\"Habilidade a retomar\">Relacionar hábitos e saúde</td><td data-rotulo=\"Ideia de aula\">Análise de rótulos de alimentos trazidos de casa. Tabela comparativa.</td></tr><tr><td data-rotulo=\"Componente\">Geografia</td><td data-rotulo=\"Habilidade a retomar\">Ler mapas e legendas</td><td data-rotulo=\"Ideia de aula\">Mapa do bairro: localizar a escola, traçar o caminho de casa, criar legenda.</td></tr><tr><td data-rotulo=\"Componente\">História</td><td data-rotulo=\"Habilidade a retomar\">Ordenar fatos no tempo</td><td data-rotulo=\"Ideia de aula\">Linha do tempo da própria vida e, depois, de um período estudado.</td></tr><tr><td data-rotulo=\"Componente\">Língua Inglesa</td><td data-rotulo=\"Habilidade a retomar\">Compreender instruções simples</td><td data-rotulo=\"Ideia de aula\">Jogo de comandos em duplas. Um lê, o outro executa.</td></tr></tbody></table></div><div class=\"nota\"><b>Depois da aula</b><br/>Peça que os alunos façam a trilha daquela habilidade ao longo da semana. Na semana seguinte, o mapa mostra quem avançou.</div>"},{"id":"c19","titulo":"O reforço dentro da aula","html":"<p>O reforço acontece em casa e na escola. Na escola, três formatos funcionam bem, conforme os equipamentos disponíveis.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Formato</th><th>Como funciona</th><th>Quando usar</th><th>Cuidados</th></tr></thead><tbody><tr><td data-rotulo=\"Formato\">Turma inteira</td><td data-rotulo=\"Como funciona\">Todos os alunos estudam a própria trilha, cada um em um equipamento, por trinta a quarenta minutos.</td><td data-rotulo=\"Quando usar\">Quando há um equipamento por aluno.</td><td data-rotulo=\"Cuidados\">O professor circula, observa as telas e atende. Não é hora de corrigir provas.</td></tr><tr><td data-rotulo=\"Formato\">Rodízio</td><td data-rotulo=\"Como funciona\">Metade da turma no reforço, metade em atividade com o professor. Depois trocam.</td><td data-rotulo=\"Quando usar\">Um equipamento para cada dois alunos.</td><td data-rotulo=\"Cuidados\">A atividade com o professor atende primeiro quem mais precisa.</td></tr><tr><td data-rotulo=\"Formato\">Estação</td><td data-rotulo=\"Como funciona\">Uma das estações da aula é o reforço, com poucos equipamentos.</td><td data-rotulo=\"Quando usar\">Poucos equipamentos.</td><td data-rotulo=\"Cuidados\">Instrução escrita na mesa e tempo marcado.</td></tr></tbody></table></div><h3>Antes, durante e depois</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Momento\">Antes</td><td data-rotulo=\"O que fazer\">Conferir os equipamentos e a conexão. Ter à mão a lista de quem precisa de novo acesso. Dizer à turma o objetivo: \"hoje cada um avança uma etapa da sua trilha\".</td></tr><tr><td data-rotulo=\"Momento\">Durante</td><td data-rotulo=\"O que fazer\">Circular. Perguntar ao aluno o que ele está estudando e pedir que explique uma questão. Anotar quem trava sempre no mesmo ponto.</td></tr><tr><td data-rotulo=\"Momento\">Depois</td><td data-rotulo=\"O que fazer\">Reservar cinco minutos: \"o que você aprendeu hoje?\" Registrar quem precisa de conversa individual.</td></tr></tbody></table></div><h3>O que observar enquanto os alunos estudam</h3><ul><li>Quem responde depressa demais, sem ler.</li><li>Quem pede a dica antes de tentar.</li><li>Quem fica parado na mesma questão.</li><li>Quem ajuda o colega respondendo por ele.</li><li>Quem avança e explica bem: possível apoio para os demais.</li></ul><div class=\"nota alerta\"><b>Ninguém responde pelo aluno</b><br/>Quando um colega, um professor ou um familiar responde, a plataforma entende que o aluno já sabe e deixa de ensinar aquele conteúdo. Oriente a turma: ajudar é explicar, e não dar a resposta.</div>"},{"id":"c20","titulo":"Quando faltam equipamentos ou internet","html":"<p>Nenhum aluno pode ficar para trás por não ter aparelho ou conexão. A escola é responsável por oferecer alternativas, e o professor é quem percebe primeiro quem precisa delas.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Alternativa</th></tr></thead><tbody><tr><td data-rotulo=\"Situação\">Aluno sem aparelho em casa</td><td data-rotulo=\"Alternativa\">Horário fixo na escola, no contraturno ou em parte de uma aula. Avisar a direção.</td></tr><tr><td data-rotulo=\"Situação\">Aluno sem internet em casa</td><td data-rotulo=\"Alternativa\">Uso na escola. Informar a direção, que registra a necessidade.</td></tr><tr><td data-rotulo=\"Situação\">Aparelho compartilhado com irmãos</td><td data-rotulo=\"Alternativa\">Combinar com a família um horário para cada um. Sessões curtas, de vinte minutos.</td></tr><tr><td data-rotulo=\"Situação\">Internet instável na escola</td><td data-rotulo=\"Alternativa\">Atividade de reserva sobre a mesma habilidade, em papel. Comunicar à direção.</td></tr><tr><td data-rotulo=\"Situação\">Poucos equipamentos para a turma</td><td data-rotulo=\"Alternativa\">Rodízio ou estação.</td></tr><tr><td data-rotulo=\"Situação\">Aluno esqueceu como entrar</td><td data-rotulo=\"Alternativa\">Pedir novo acesso à direção. Não emprestar o acesso de outro aluno.</td></tr></tbody></table></div><h3>Como descobrir quem não tem acesso em casa</h3><ul><li>Pergunte de forma reservada, nunca diante da turma.</li><li>Observe as células vazias do mapa.</li><li>Use um bilhete simples aos responsáveis, com resposta por escrito.</li><li>Passe a lista à direção, que organiza os horários na escola.</li></ul><h3>Atividade de reserva</h3><p>Mantenha, para cada habilidade prioritária da turma, uma folha de atividades com a mesma sequência da trilha: relembrar, exemplo, prática, aplicação e explicação. Ela serve para os dias sem conexão e para os alunos que ficaram sem equipamento.</p><div class=\"nota\"><b>Não compare quem tem com quem não tem</b><br/>O aluno que pratica menos por falta de acesso não deve ser cobrado como os demais. A cobrança é da escola, que precisa garantir o acesso.</div>"},{"id":"c21","titulo":"Ensinar o aluno a usar o tutor","html":"<p>O tutor ajuda o aluno a pensar. Ele faz perguntas, dá dicas e mostra o caminho, sem entregar a resposta. Muitos alunos estranham no início, porque esperam a resposta pronta. Vale ensinar a usar.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O tutor faz</th><th>O tutor não faz</th></tr></thead><tbody><tr><td data-rotulo=\"O tutor faz\">Pergunta o que o aluno já tentou.</td><td data-rotulo=\"O tutor não faz\">Não dá a resposta do exercício.</td></tr><tr><td data-rotulo=\"O tutor faz\">Dá uma dica de cada vez.</td><td data-rotulo=\"O tutor não faz\">Não resolve no lugar do aluno.</td></tr><tr><td data-rotulo=\"O tutor faz\">Explica de outro jeito quando o aluno não entende.</td><td data-rotulo=\"O tutor não faz\">Não reescreve o texto do aluno.</td></tr><tr><td data-rotulo=\"O tutor faz\">Mostra um exemplo parecido.</td><td data-rotulo=\"O tutor não faz\">Não dá nota.</td></tr><tr><td data-rotulo=\"O tutor faz\">Aponta onde está o erro.</td><td data-rotulo=\"O tutor não faz\">Não conversa sobre assuntos fora do estudo.</td></tr></tbody></table></div><h3>Como explicar à turma</h3><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · apresentando o tutor</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">O tutor é como um colega que sabe a matéria e não deixa você copiar. Ele ajuda você a chegar lá.</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Mas ele não dá a resposta!</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Não dá. Se ele desse, você acertaria o exercício e continuaria sem saber. O que ele perguntou a você?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Perguntou o que eu já tinha tentado.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">E o que você respondeu? Vamos escrever juntos.</div></div></div><h3>Boas perguntas para o aluno fazer ao tutor</h3><ul><li>\"Não entendi esta palavra do enunciado.\"</li><li>\"Pode me dar um exemplo parecido?\"</li><li>\"Fiz assim. Onde errei?\"</li><li>\"Pode explicar de outro jeito?\"</li><li>\"Por que esta resposta está errada?\"</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Se o aluno</th><th>Oriente</th></tr></thead><tbody><tr><td data-rotulo=\"Se o aluno\">Pede a resposta várias vezes</td><td data-rotulo=\"Oriente\">A dizer ao tutor o que já tentou.</td></tr><tr><td data-rotulo=\"Se o aluno\">Escreve só \"não sei\"</td><td data-rotulo=\"Oriente\">A dizer qual parte não entendeu.</td></tr><tr><td data-rotulo=\"Se o aluno\">Não lê as dicas</td><td data-rotulo=\"Oriente\">A ler em voz baixa e repetir com as próprias palavras.</td></tr><tr><td data-rotulo=\"Se o aluno\">Desiste</td><td data-rotulo=\"Oriente\">A voltar ao exemplo guiado.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Se o tutor errar</b><br/>Uma dica inadequada ou um conteúdo com erro deve ser comunicado à direção, com a descrição do que aconteceu. O registro ajuda a corrigir para toda a rede.</div>"},{"id":"c22","titulo":"A conversa individual sobre a evolução","html":"<p>Uma conversa de três minutos com cada aluno, uma vez por mês, faz mais pelo engajamento do que qualquer cobrança coletiva. O aluno precisa ver que avançou e saber qual é o próximo passo.</p><ol class=\"passos\"><li>Comece pelo que melhorou: uma habilidade que saiu de Ainda não ou de Quase lá.</li><li>Pergunte como ele conseguiu.</li><li>Mostre a próxima habilidade e pergunte o que ele acha dela.</li><li>Combine uma meta pequena para a semana.</li><li>Pergunte do que ele precisa: horário, equipamento, ajuda.</li></ol><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · três minutos com o aluno</div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Olha só: no mês passado você estava em Ainda não em frações. Agora está em Quase lá. O que você fez de diferente?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Fiz a trilha em casa, à noite.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Deu certo. A próxima é comparar frações. O que você acha?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Acho difícil.</div></div><div class=\"f\"><div class=\"q\">Professor</div><div class=\"b\">Vamos fazer o exemplo guiado juntos na quinta. Até lá, você consegue fazer a etapa Relembrar?</div></div><div class=\"f o\"><div class=\"q\">Aluno</div><div class=\"b\">Consigo.</div></div></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Diga</th><th>Evite</th></tr></thead><tbody><tr><td data-rotulo=\"Diga\">\"Você recuperou duas habilidades neste mês.\"</td><td data-rotulo=\"Evite\">\"Você ainda está atrasado.\"</td></tr><tr><td data-rotulo=\"Diga\">\"O que te ajudou?\"</td><td data-rotulo=\"Evite\">\"Por que você não fez?\"</td></tr><tr><td data-rotulo=\"Diga\">\"Qual é o seu próximo passo?\"</td><td data-rotulo=\"Evite\">\"Você precisa se esforçar mais.\"</td></tr><tr><td data-rotulo=\"Diga\">\"Do que você precisa?\"</td><td data-rotulo=\"Evite\">\"Seus colegas já terminaram.\"</td></tr></tbody></table></div><h3>Motivar sem ranking</h3><ul><li>Mostre o avanço da turma como um todo, sem nomes.</li><li>Comemore habilidades recuperadas, e não posições.</li><li>Reconheça a constância: quem estudou toda semana.</li><li>Não publique listas de quem fez e de quem não fez.</li><li>Não use o reforço como condição para o recreio ou para outras atividades.</li></ul><div class=\"nota\"><b>A plataforma não mostra nota ao aluno</b><br/>O aluno vê a própria evolução, sem nota e sem comparação com colegas. Mantenha a mesma lógica nas conversas em sala.</div>"},{"id":"c23","titulo":"O reforço e a avaliação da escola","html":"<p>O reforço e a avaliação escolar têm papéis diferentes. Misturá-los prejudica os dois.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th></th><th>Reforço escolar</th><th>Avaliação da escola</th></tr></thead><tbody><tr><td data-rotulo=\"\">Para que serve</td><td data-rotulo=\"Reforço escolar\">Recuperar habilidades e mostrar o que retomar.</td><td data-rotulo=\"Avaliação da escola\">Verificar a aprendizagem e registrar o resultado do período.</td></tr><tr><td data-rotulo=\"\">Gera nota</td><td data-rotulo=\"Reforço escolar\">Não.</td><td data-rotulo=\"Avaliação da escola\">Sim, conforme as normas da rede.</td></tr><tr><td data-rotulo=\"\">Quem decide</td><td data-rotulo=\"Reforço escolar\">O aluno avança no próprio ritmo.</td><td data-rotulo=\"Avaliação da escola\">O professor, com critérios definidos.</td></tr><tr><td data-rotulo=\"\">O erro</td><td data-rotulo=\"Reforço escolar\">É informação para ensinar.</td><td data-rotulo=\"Avaliação da escola\">Conta no resultado.</td></tr><tr><td data-rotulo=\"\">Uso pelo professor</td><td data-rotulo=\"Reforço escolar\">Planejar a retomada e formar grupos.</td><td data-rotulo=\"Avaliação da escola\">Decidir encaminhamentos e registrar no diário.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pode</th><th>Não pode</th></tr></thead><tbody><tr><td data-rotulo=\"Pode\">Usar o mapa para decidir o que retomar antes de uma prova.</td><td data-rotulo=\"Não pode\">Transformar o nível do aluno na plataforma em nota.</td></tr><tr><td data-rotulo=\"Pode\">Considerar o empenho no reforço ao conversar com o aluno e a família.</td><td data-rotulo=\"Não pode\">Dar ponto extra por tempo de uso ou por número de questões.</td></tr><tr><td data-rotulo=\"Pode\">Levar ao conselho de classe as habilidades recuperadas.</td><td data-rotulo=\"Não pode\">Reprovar ou aprovar com base no mapa.</td></tr><tr><td data-rotulo=\"Pode\">Usar a mesma sequência da trilha em atividades de recuperação.</td><td data-rotulo=\"Não pode\">Punir quem não praticou por falta de acesso.</td></tr></tbody></table></div><h3>Por que não vira nota</h3><ul><li>Quando vale nota, o aluno procura acertar a qualquer custo, inclusive pedindo que outro responda.</li><li>O diagnóstico perde a exatidão e a trilha deixa de ensinar o que ele precisa.</li><li>Alunos sem acesso em casa seriam prejudicados.</li><li>O erro deixa de ser visto como parte do aprendizado.</li></ul><div class=\"nota\"><b>No conselho de classe</b><br/>O mapa da turma ajuda a responder a duas perguntas do conselho: o que esta turma ainda não aprendeu, e quem avançou no bimestre.</div>"},{"id":"c24","titulo":"O bimestre com o reforço","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Semana</th><th>O que fazer</th></tr></thead><tbody><tr><td data-rotulo=\"Semana\">1</td><td data-rotulo=\"O que fazer\">Conferir se todos os alunos têm acesso. Ver o mapa. Escolher duas habilidades prioritárias para a turma.</td></tr><tr><td data-rotulo=\"Semana\">2</td><td data-rotulo=\"O que fazer\">Aula de retomada da primeira habilidade. Combinar com a turma a prática semanal.</td></tr><tr><td data-rotulo=\"Semana\">3</td><td data-rotulo=\"O que fazer\">Uso do reforço em sala, em um dos três formatos. Observar quem trava.</td></tr><tr><td data-rotulo=\"Semana\">4</td><td data-rotulo=\"O que fazer\">Ver o mapa de novo. Conversas individuais com um terço da turma.</td></tr><tr><td data-rotulo=\"Semana\">5</td><td data-rotulo=\"O que fazer\">Aula de retomada da segunda habilidade. Avisar as famílias dos alunos que precisam de reforço.</td></tr><tr><td data-rotulo=\"Semana\">6</td><td data-rotulo=\"O que fazer\">Grupos por nível ou estações. Conversas individuais com outro terço.</td></tr><tr><td data-rotulo=\"Semana\">7</td><td data-rotulo=\"O que fazer\">Uso do reforço em sala. Conversas com o último terço.</td></tr><tr><td data-rotulo=\"Semana\">8</td><td data-rotulo=\"O que fazer\">Balanço: quantas habilidades a turma recuperou? O que levar ao conselho de classe?</td></tr></tbody></table></div><h3>O que levar ao conselho de classe</h3><ul class=\"chk\"><li><span></span>As duas habilidades que a turma mais recuperou.</li><li><span></span>As duas em que a maioria continua em Ainda não.</li><li><span></span>Os alunos que avançaram, para reconhecimento.</li><li><span></span>Os alunos com muitas células vazias, com o motivo que você conhece.</li><li><span></span>O que você pretende mudar no bimestre seguinte.</li></ul><h3>Meia hora por semana</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Tarefa</th></tr></thead><tbody><tr><td data-rotulo=\"Tempo\">10 min</td><td data-rotulo=\"Tarefa\">Olhar o mapa das turmas e responder às três perguntas.</td></tr><tr><td data-rotulo=\"Tempo\">10 min</td><td data-rotulo=\"Tarefa\">Ajustar o plano da semana: o que retomar e com quem.</td></tr><tr><td data-rotulo=\"Tempo\">5 min</td><td data-rotulo=\"Tarefa\">Enviar avisos às famílias, quando for o caso.</td></tr><tr><td data-rotulo=\"Tempo\">5 min</td><td data-rotulo=\"Tarefa\">Anotar o que levar à coordenação.</td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · o meu bimestre</div><div class=\"q\"><b>1.</b> Que duas habilidades você vai priorizar em uma das suas turmas?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Em que dia da semana você vai olhar o mapa?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Qual formato de uso em sala cabe na sua escola?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c25","titulo":"Mensagens e reuniões com os responsáveis","html":"<p>Os responsáveis acompanham a evolução do aluno pela própria conta. O professor completa essa informação quando indica uma matéria para reforço e quando conversa nas reuniões.</p><h3>Modelos de mensagem</h3><div class=\"rapido\"><p><b>Indicação de reforço:</b> \"Olá. Sou a professora de Matemática do Rafael. Ele tem se esforçado nas aulas. Para avançar em frações, seria bom estudar a trilha de Matemática duas ou três vezes por semana, por vinte minutos. Se precisar de ajuda para entrar, procure a secretaria da escola.\"</p><p><b>Reconhecimento:</b> \"Olá. Quero contar que a Júlia recuperou três habilidades de leitura neste mês. Ela está estudando com constância. Parabéns a ela e à família pelo apoio.\"</p><p><b>Falta de prática:</b> \"Olá. Notei que o Marcos não tem entrado no reforço. Aconteceu alguma coisa? Se houver dificuldade com aparelho ou internet, a escola pode reservar um horário para ele estudar aqui.\"</p></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Uma boa mensagem</th><th>Uma mensagem a evitar</th></tr></thead><tbody><tr><td data-rotulo=\"Uma boa mensagem\">Começa por algo positivo e verdadeiro.</td><td data-rotulo=\"Uma mensagem a evitar\">Começa pela queixa.</td></tr><tr><td data-rotulo=\"Uma boa mensagem\">Diz o que fazer, quanto e quando.</td><td data-rotulo=\"Uma mensagem a evitar\">Diz apenas \"precisa estudar mais\".</td></tr><tr><td data-rotulo=\"Uma boa mensagem\">Oferece ajuda.</td><td data-rotulo=\"Uma mensagem a evitar\">Cobra o que a família talvez não possa dar.</td></tr><tr><td data-rotulo=\"Uma boa mensagem\">É curta.</td><td data-rotulo=\"Uma mensagem a evitar\">É longa e cheia de termos técnicos.</td></tr><tr><td data-rotulo=\"Uma boa mensagem\">Não cita outros alunos.</td><td data-rotulo=\"Uma mensagem a evitar\">Compara com colegas.</td></tr></tbody></table></div><h3>Na reunião de responsáveis</h3><ol class=\"passos\"><li>Mostre, com dados de exemplo ou sem nomes, como é a tela do aluno.</li><li>Explique os três níveis com palavras simples.</li><li>Diga o que a família pode fazer: horário fixo, lugar calmo, perguntar o que aprendeu.</li><li>Reforce que ninguém deve responder pelo aluno.</li><li>Pergunte quem não tem aparelho ou internet e anote de forma reservada.</li><li>Ofereça conversas individuais ao final.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta do responsável</th><th>Resposta possível</th></tr></thead><tbody><tr><td data-rotulo=\"Pergunta do responsável\">\"Ele está em Ainda não. Vai reprovar?\"</td><td data-rotulo=\"Resposta possível\">\"Não. O reforço não dá nota. Mostra o que ele precisa estudar agora.\"</td></tr><tr><td data-rotulo=\"Pergunta do responsável\">\"Por que ele está estudando coisa de outro ano?\"</td><td data-rotulo=\"Resposta possível\">\"Porque essa é a base que falta. Recuperando a base, o conteúdo do ano fica mais fácil.\"</td></tr><tr><td data-rotulo=\"Pergunta do responsável\">\"Quanto tempo por dia?\"</td><td data-rotulo=\"Resposta possível\">\"De vinte a trinta minutos, três vezes por semana, já faz diferença.\"</td></tr><tr><td data-rotulo=\"Pergunta do responsável\">\"Posso ajudar nas respostas?\"</td><td data-rotulo=\"Resposta possível\">\"Ajude a ler e a entender a pergunta. A resposta precisa ser dele.\"</td></tr></tbody></table></div>"},{"id":"c26","titulo":"Perguntas frequentes","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Pergunta</th><th>Resposta</th></tr></thead><tbody><tr><td data-rotulo=\"Pergunta\">Preciso aplicar ou liberar o diagnóstico?</td><td data-rotulo=\"Resposta\">Não. O aluno faz o diagnóstico ao estudar. A coordenação pode abrir diagnósticos para a rede.</td></tr><tr><td data-rotulo=\"Pergunta\">Preciso corrigir as atividades do reforço?</td><td data-rotulo=\"Resposta\">Não. O retorno é imediato. Você acompanha pelo mapa.</td></tr><tr><td data-rotulo=\"Pergunta\">O aluno pode estudar outra matéria além da minha?</td><td data-rotulo=\"Resposta\">Sim. Ele escolhe entre as matérias do ano dele.</td></tr><tr><td data-rotulo=\"Pergunta\">O mapa mostra todas as minhas turmas?</td><td data-rotulo=\"Resposta\">Mostra as turmas atribuídas a você. Se faltar alguma, fale com a direção.</td></tr><tr><td data-rotulo=\"Pergunta\">Um aluno novo não aparece.</td><td data-rotulo=\"Resposta\">A direção precisa incluí-lo na turma.</td></tr><tr><td data-rotulo=\"Pergunta\">O aluno diz que a plataforma está fácil demais.</td><td data-rotulo=\"Resposta\">Ele pode estar em uma habilidade que já domina. Ao acertar, a trilha avança.</td></tr><tr><td data-rotulo=\"Pergunta\">O aluno diz que está difícil demais.</td><td data-rotulo=\"Resposta\">Oriente a refazer o exemplo guiado e a usar as dicas do tutor. Verifique a habilidade de base.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso usar o reforço como tarefa de casa?</td><td data-rotulo=\"Resposta\">Pode indicar, sem atribuir nota e garantindo alternativa a quem não tem acesso.</td></tr><tr><td data-rotulo=\"Pergunta\">E se o responsável responder pelo aluno?</td><td data-rotulo=\"Resposta\">Converse com a família e explique por que isso prejudica o aluno.</td></tr><tr><td data-rotulo=\"Pergunta\">Quanto tempo leva para um aluno mudar de nível?</td><td data-rotulo=\"Resposta\">Varia. O que mais pesa é a constância: pouco tempo, várias vezes por semana.</td></tr><tr><td data-rotulo=\"Pergunta\">Posso mostrar o mapa à turma?</td><td data-rotulo=\"Resposta\">Não com os nomes. Mostre o avanço geral da turma.</td></tr><tr><td data-rotulo=\"Pergunta\">O reforço substitui a recuperação da escola?</td><td data-rotulo=\"Resposta\">Não. Ele apoia. A recuperação prevista nas normas da rede continua.</td></tr><tr><td data-rotulo=\"Pergunta\">Esqueci a minha senha.</td><td data-rotulo=\"Resposta\">Use a opção de recuperar o acesso ou procure a direção.</td></tr><tr><td data-rotulo=\"Pergunta\">Encontrei um erro em uma questão.</td><td data-rotulo=\"Resposta\">Comunique à direção, com a descrição da questão.</td></tr></tbody></table></div>"},{"id":"c27","titulo":"Mais exemplos de uso","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma que travava em problemas</div><p><b>Situação.</b> No 6º ano, a turma resolve contas, mas erra os problemas. O mapa mostra a maioria em Ainda não em interpretação de enunciados.</p><p><b>O que fazer.</b></p><ol><li>Combine com o professor de Língua Portuguesa uma retomada de leitura de enunciados.</li><li>Nas aulas de Matemática, peça que os alunos digam com as próprias palavras o que o problema pergunta, antes de calcular.</li><li>Indique a trilha de leitura no reforço.</li><li>Depois de três semanas, confira o mapa.</li></ol><p><b>Resultado esperado.</b> Os erros de interpretação diminuem, e os alunos passam a identificar a pergunta do problema.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o aluno que respondia rápido demais</div><p><b>Situação.</b> Um aluno termina as sessões em poucos minutos e continua em Ainda não.</p><p><b>O que fazer.</b></p><ol><li>Sente-se ao lado dele durante uma sessão.</li><li>Peça que leia a questão em voz baixa e explique o que entendeu.</li><li>Mostre como usar a dica do tutor.</li><li>Combine uma meta: três questões bem pensadas, em vez de vinte no impulso.</li></ol><p><b>Resultado esperado.</b> O aluno passa a ler os enunciados e avança de nível.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a mãe que fazia junto</div><p><b>Situação.</b> Uma aluna aparece em Domina em quase tudo, mas em sala não resolve as mesmas questões.</p><p><b>O que fazer.</b></p><ol><li>Converse com a aluna, sem acusar: \"Como você estuda em casa?\"</li><li>Fale com a responsável e agradeça o interesse.</li><li>Explique que, quando outra pessoa responde, a plataforma deixa de ensinar o que a aluna precisa.</li><li>Sugira que a mãe ajude a ler a pergunta e deixe a resposta com a filha.</li></ol><p><b>Resultado esperado.</b> A aluna volta a estudar no próprio nível e começa a avançar de verdade.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a aula sem internet</div><p><b>Situação.</b> No dia reservado para o reforço, a conexão da escola cai.</p><p><b>O que fazer.</b></p><ol><li>Use a atividade de reserva da habilidade prioritária.</li><li>Organize a turma em duplas, com a sequência relembrar, exemplo, prática.</li><li>Comunique o problema à direção.</li><li>Remarque a sessão para a mesma semana.</li></ol><p><b>Resultado esperado.</b> A aula acontece, e a turma não perde a semana de prática.</p></div>"},{"id":"c28","titulo":"O meu plano de trinta dias","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Semana</th><th>Ação</th><th>Feito</th></tr></thead><tbody><tr><td data-rotulo=\"Semana\">1</td><td data-rotulo=\"Ação\">Entrei, conferi as minhas turmas e li o mapa de uma delas.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">1</td><td data-rotulo=\"Ação\">Verifiquei quais alunos não têm acesso e avisei a direção.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">2</td><td data-rotulo=\"Ação\">Escolhi uma habilidade e dei uma aula de retomada.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">2</td><td data-rotulo=\"Ação\">Apresentei o tutor à turma.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">3</td><td data-rotulo=\"Ação\">Usei o reforço em sala em um dos três formatos.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">3</td><td data-rotulo=\"Ação\">Conversei individualmente com cinco alunos.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">4</td><td data-rotulo=\"Ação\">Enviei avisos às famílias de quem precisa de reforço.</td><td data-rotulo=\"Feito\"></td></tr><tr><td data-rotulo=\"Semana\">4</td><td data-rotulo=\"Ação\">Comparei o mapa com o do início do mês.</td><td data-rotulo=\"Feito\"></td></tr></tbody></table></div><div class=\"pratica\"><div class=\"tt\">Para praticar · balanço do mês</div><div class=\"q\"><b>1.</b> O que mudou no mapa da turma em trinta dias?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> O que funcionou melhor?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> O que você vai mudar no próximo mês?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>4.</b> O que você precisa pedir à coordenação ou à direção?<div class=\"ln\"></div><div class=\"ln\"></div></div></div><div class=\"nota\"><b>Comece pequeno</b><br/>Uma turma, uma habilidade e uma conversa por semana. Com o hábito formado, é fácil estender às outras turmas.</div>"},{"id":"c29","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Quem define o caminho de estudo do aluno no reforço?</p><ol type=\"a\"><li>A plataforma, a partir do diagnóstico do aluno.</li><li>A direção da escola.</li><li>O responsável.</li><li>O professor, toda semana.</li></ol></div><div class=\"qz\"><p><b>2.</b> No mapa, uma coluna com muitos alunos em Ainda não indica:</p><ol type=\"a\"><li>Um erro da plataforma.</li><li>Que a turma não tem acesso.</li><li>Um aluno com dificuldade.</li><li>Uma habilidade para retomar com a turma.</li></ol></div><div class=\"qz\"><p><b>3.</b> O tutor com inteligência artificial:</p><ol type=\"a\"><li>Orienta com perguntas e dicas.</li><li>Substitui o professor.</li><li>Entrega a resposta ao aluno.</li><li>Dá nota ao aluno.</li></ol></div><div class=\"qz\"><p><b>4.</b> Para avisar um responsável de que o aluno precisa de reforço, use:</p><ol type=\"a\"><li>Atividades.</li><li>Avisar as famílias.</li><li>Abrir aula.</li><li>Trilhas.</li></ol></div><div class=\"qz\"><p><b>5.</b> Qual atitude respeita a ética no uso da plataforma?</p><ol type=\"a\"><li>Dar nota pelo nível no mapa.</li><li>Conversar em particular com o aluno que precisa de atenção.</li><li>Responder pelo aluno para ele avançar.</li><li>Mostrar o mapa com nomes no projetor.</li></ol></div><div class=\"qz\"><p><b>6.</b> Um aluno não tem equipamento em casa. O que fazer?</p><ol type=\"a\"><li>Avisar o responsável de que a culpa é dele.</li><li>Cobrar a prática mesmo assim.</li><li>Levar o caso à direção para buscar uma alternativa de acesso.</li><li>Tirar o aluno do reforço.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> a) A plataforma, a partir do diagnóstico do aluno. O reforço é individual e não depende do professor.</p><p><b>2.</b> d) Uma habilidade para retomar com a turma. A leitura pela coluna mostra a habilidade.</p><p><b>3.</b> a) Orienta com perguntas e dicas. Ele não entrega a resposta.</p><p><b>4.</b> b) Avisar as famílias. O responsável recebe no celular.</p><p><b>5.</b> b) Conversar em particular com o aluno que precisa de atenção. O mapa não serve para expor nem para dar nota.</p><p><b>6.</b> c) Levar o caso à direção para buscar uma alternativa de acesso. Equidade: ninguém pode ser prejudicado por falta de acesso.</p></div>"},{"id":"c30","titulo":"Glossário","html":"<dl><dt>BNCC</dt><dd>Base Nacional Comum Curricular. Define as habilidades que o aluno deve desenvolver em cada ano e componente.</dd><dt>Componente curricular</dt><dd>Cada matéria do currículo: Língua Portuguesa, Matemática, Ciências e as demais.</dd><dt>Diagnóstico</dt><dd>Conjunto curto de questões que mostra quais habilidades o aluno já domina.</dd><dt>Habilidade</dt><dd>O que o aluno deve saber fazer. É a unidade que a plataforma acompanha.</dd><dt>Habilidade recuperada</dt><dd>Habilidade em que o aluno saiu de Ainda não ou Quase lá e chegou a Domina.</dd><dt>Mapa da turma</dt><dd>Quadro de alunos por habilidade, com o nível de domínio de cada um.</dd><dt>Nível de domínio</dt><dd>Situação do aluno em uma habilidade: Ainda não, Quase lá ou Domina.</dd><dt>Pré-requisito</dt><dd>Habilidade anterior que serve de base para outra.</dd><dt>Responsável</dt><dd>Adulto que cuida do aluno e o acompanha na plataforma.</dd><dt>Trilha</dt><dd>Sequência de estudo de uma habilidade, em cinco etapas.</dd><dt>Tutor</dt><dd>Apoio com inteligência artificial que orienta o aluno com perguntas e dicas.</dd></dl>"},{"id":"c31","titulo":"Guia rápido","html":"<div class=\"rapido\"><h3>Toda semana, em 15 minutos</h3><ol class=\"passos\"><li><b>Mapa da turma</b>: filtre pelo seu componente.</li><li>Anote a habilidade com mais alunos em Ainda não.</li><li>Veja quem não praticou e converse com o aluno.</li><li><b>Avisar as famílias</b>: indique reforço a quem precisa.</li><li><b>Retornos para revisar</b>: confira se há pendências.</li></ol><h3>Lembre-se</h3><ul><li>O reforço é individual e não depende de você para acontecer.</li><li>O mapa não é nota. Ele mostra o momento do aluno.</li><li>O tutor não entrega a resposta.</li><li>Dados de aluno não saem da plataforma.</li></ul><h3>Precisa de ajuda?</h3><p>Acesso de aluno e de responsável: direção da escola. Dúvida pedagógica: coordenação. Erro na plataforma: direção, que aciona a Secretaria.</p></div>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"Um aluno do 7º ano estuda no reforço uma habilidade do 5º. Isso significa que:","alternativas":["A plataforma errou.","Essa é a base que falta para o conteúdo do ano.","Ele foi rebaixado de ano.","Ele deve refazer o 5º ano."],"correta":1,"explicacao":"A plataforma volta à origem da dificuldade."},{"pergunta":"Uma coluna do mapa quase toda em Ainda não pede:","alternativas":["Uma prova.","Nenhuma ação.","Atendimento a um só aluno.","Retomada da habilidade com a turma toda."],"correta":3,"explicacao":"A turma não domina aquela habilidade."},{"pergunta":"Com um equipamento para cada dois alunos, o formato indicado é:","alternativas":["Só em casa.","Turma inteira.","Rodízio.","Suspender o reforço."],"correta":2,"explicacao":"Metade no reforço, metade com o professor."},{"pergunta":"O tutor do reforço:","alternativas":["Dá a resposta quando o aluno insiste.","Orienta com perguntas e dicas, sem dar a resposta.","Atribui nota.","Substitui o professor."],"correta":1,"explicacao":"A resposta pronta não ensina."},{"pergunta":"O nível do aluno na plataforma:","alternativas":["Não vira nota. Orienta o que retomar.","Define a aprovação.","Deve ser divulgado à turma.","Vira nota no boletim."],"correta":0,"explicacao":"Reforço e avaliação têm papéis diferentes."},{"pergunta":"Para motivar a turma, o professor:","alternativas":["Mostra o avanço geral e conversa individualmente.","Dá ponto por tempo de uso.","Tira o recreio de quem não fez.","Publica o ranking."],"correta":0,"explicacao":"Sem ranking e sem punição."},{"pergunta":"Um aluno não pratica por não ter internet em casa. O professor:","alternativas":["Desconta nota.","Ignora.","Cobra do aluno.","Avisa a direção, que organiza horário na escola."],"correta":3,"explicacao":"A escola garante o acesso."},{"pergunta":"Quando um familiar responde pelo aluno:","alternativas":["O nível fica mais exato.","O aluno avança mais rápido.","A plataforma deixa de ensinar o que ele precisa.","Não muda nada."],"correta":2,"explicacao":"O diagnóstico perde a exatidão."}];
